{"command":"npm test && node -e "
import assert from 'node:assert/strict';
import { MuxSession } from './src/net/mux_session.mjs';

const s = new MuxSession();
const r1 = s.onDataFrame({ channelId: 1, payload: '尾帧完整载荷测试', fin: false });
assert.deepEqual(r1, { handled: true, payload: '尾帧完整载荷测试', fin: false });
assert.equal(s.metrics.dataBytes, 24);

s.state = 'DRAINING';
assert.deepEqual(s.onOpenChannel({ channelId: 2 }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.deepEqual(s.onWindowUpdate({ delta: 100 }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.deepEqual(s.onPingFrame({ nonce: 42 }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.deepEqual(s.onDataFrame({ channelId: 1, payload: '测试', fin: false }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.deepEqual(s.onDataFrame({ channelId: 1, payload: '测试', fin: 1 }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.equal(s.metrics.droppedFrames, 5);

const r2 = s.onDataFrame({ channelId: 1, payload: '尾帧完整载荷测试', fin: true });
assert.deepEqual(r2, { handled: true, payload: '尾帧完整载荷测试', fin: true });
assert.equal(s.metrics.dataBytes, 48);
assert.equal(s.metrics.droppedFrames, 5);

s.state = 'CLOSED';
assert.deepEqual(s.onDataFrame({ channelId: 1, payload: '尾帧完整载荷测试', fin: true }), { handled: false, reason: 'SESSION_INACTIVE' });
assert.equal(s.metrics.droppedFrames, 6);
console.log('ALL PASSED');
""}

